const DEFAULT_USERS = [{ id: "emily", name: "Emily", role: "ADMIN" }, { id: "seller-1", name: "Consultor 1", role: "OPERACIONAL" }, { id: "seller-2", name: "Consultor 2", role: "OPERACIONAL" }, { id: "seller-3", name: "Consultor 3", role: "OPERACIONAL" }, { id: "seller-4", name: "Consultor 4", role: "OPERACIONAL" }, { id: "assistant", name: "Assistente", role: "OPERACIONAL" }];
let USERS = DEFAULT_USERS;
const VISIT_TYPES = [["RELATIONSHIP", "Relacionamento"], ["PROSPECTING", "Prospecção de cliente"], ["CLOSING", "Fechamento de negócio"]];
const NOT_DONE_REASONS = ["Cliente não estava", "Cliente remarcou", "Emergência do cliente", "Emergência do consultor", "Outro"];
const PRODUCT_LINES = ["Herbicida", "Semente", "Adubo", "Defensivo", "Nutrição vegetal", "Saúde animal", "Outro"];
const EMPTY = { clients: [], farms: [], plans: [], visits: [] };
const text = (value, max = 1000) => String(value ?? "").trim().slice(0, max);
const idFor = (items) => Math.max(0, ...items.map((item) => Number(item.id) || 0)) + 1;
const money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
const dateLabel = (value) => new Date(`${String(value).slice(0, 10)}T12:00:00`).toLocaleDateString("pt-BR");
function mondayOf(value = new Date()) { const date = new Date(value); if (typeof value === "string") return date.toISOString().slice(0, 10); const day = date.getDay() || 7; date.setDate(date.getDate() - day + 1); date.setHours(0, 0, 0, 0); return date.toISOString().slice(0, 10); }
function inWeek(value, selectedDate) { const start = new Date(`${selectedDate}T00:00:00`); const day = start.getDay() || 7; start.setDate(start.getDate() - day + 1); const end = new Date(start); end.setDate(start.getDate() + 7); const date = new Date(`${String(value).slice(0, 10)}T00:00:00`); return date >= start && date < end; }

function normalize(raw) {
  const source = raw && typeof raw === "object" ? raw : EMPTY;
  const users = (Array.isArray(source.users) && source.users.length ? source.users : DEFAULT_USERS).map((item, index) => ({ id: text(item.id || `consultant-${index + 1}`, 40), name: text(item.name, 100), role: item.role === "ADMIN" ? "ADMIN" : "OPERACIONAL" })).filter((item) => item.id && item.name);
  return {
    users: users.length ? users : DEFAULT_USERS,
    clients: (source.clients || []).map((item, index) => ({ id: Number(item.id) || index + 1, name: text(item.name, 180), city: text(item.city, 80), state: text(item.state, 2).toUpperCase(), phone: text(item.phone, 40), whatsapp: text(item.whatsapp, 40), mainActivity: text(item.mainActivity, 100), notes: text(item.notes, 2000) })).filter((item) => item.name),
    farms: (source.farms || []).map((item, index) => ({ id: Number(item.id) || index + 1, name: text(item.name, 180), clientId: Number(item.clientId) || null, city: text(item.city, 80), state: text(item.state, 2).toUpperCase(), mainActivity: text(item.mainActivity, 100), notes: text(item.notes, 2000) })).filter((item) => item.name),
    plans: (source.plans || []).map((item, index) => ({ id: Number(item.id) || index + 1, userId: text(item.userId, 40), clientId: Number(item.clientId) || null, farmId: Number(item.farmId) || null, scheduledDate: text(item.scheduledDate, 10), status: ["PLANNED", "COMPLETED", "NOT_DONE"].includes(item.status) ? item.status : "PLANNED", notDoneReason: text(item.notDoneReason, 100), notDoneNote: text(item.notDoneNote, 500) })),
    visits: (source.visits || []).map((item, index) => ({ id: Number(item.id) || index + 1, userId: text(item.userId, 40), planId: Number(item.planId) || null, clientId: Number(item.clientId) || null, farmId: Number(item.farmId) || null, visitedAt: item.visitedAt || new Date().toISOString(), developed: text(item.developed || item.result, 2000), types: Array.isArray(item.types) ? item.types.filter((type) => VISIT_TYPES.some(([id]) => id === type)) : [], businessType: text(item.businessType, 100), saleValue: Number(item.saleValue) || 0, nextAction: text(item.nextAction, 500) })),
  };
}
function loadData() { try { const saved = localStorage.getItem(STORAGE_KEY); if (saved) return normalize(JSON.parse(saved)); return normalize(JSON.parse(localStorage.getItem(PREVIOUS_KEY) || "null")); } catch { return EMPTY; } }
function Field({ label, value, onChange, required, type = "text", placeholder, min, step }) { return <div className="source-field"><label>{label}</label><input type={type} value={value} onChange={(event) => onChange(event.target.value)} required={required} placeholder={placeholder} min={min} step={step} /></div>; }
function StateCityFields({ state, city, onChange }) { const cities = CITIES_BY_STATE[state] || []; const citiesListId = `cities-${state || "state"}`; return <div className="source-grid"><div className="source-field"><label>UF</label><select value={state} onChange={(event) => onChange({ state: event.target.value, city: "" })}>{BR_STATES.map((item) => <option key={item.sigla} value={item.sigla}>{item.sigla} — {item.nome}</option>)}</select></div><div className="source-field"><label>Cidade</label><input value={city} list={citiesListId} onChange={(event) => onChange({ state, city: event.target.value })} disabled={!state} placeholder={state ? "Digite ou selecione uma cidade" : "Selecione primeiro a UF"} /><datalist id={citiesListId}>{cities.map((item) => <option key={item} value={item} />)}</datalist></div></div>; }
function Empty({ children }) { return <div className="empty"><p>{children}</p></div>; }
function Panel({ title, children }) { return <section className="panel"><h3>{title}</h3>{children}</section>; }
function Metric({ label, value, detail }) { return <article className="metric"><span>{label}</span><strong>{value}</strong><em>{detail}</em></article>; }
function toBrazilianDate(value) { const [year, month, day] = String(value || "").slice(0, 10).split("-"); return year && month && day ? `${day}/${month}/${year}` : ""; }
function toBrazilianDateTime(value) { const [date, time = ""] = String(value || "").split("T"); return `${toBrazilianDate(date)}${time ? ` ${time.slice(0, 5)}` : ""}`.trim(); }
function validDate(day, month, year) { const date = new Date(Number(year), Number(month) - 1, Number(day)); return date.getFullYear() === Number(year) && date.getMonth() === Number(month) - 1 && date.getDate() === Number(day); }
function CalendarPicker({ value, onChange, withTime = false, required = false }) { const initial = String(value || new Date().toISOString()).slice(0, 10); const [open, setOpen] = useState(false); const [cursor, setCursor] = useState(new Date(`${initial}T12:00:00`)); useEffect(() => setCursor(new Date(`${String(value || initial).slice(0, 10)}T12:00:00`)), [value]); const first = new Date(cursor.getFullYear(), cursor.getMonth(), 1); const offset = (first.getDay() + 6) % 7; const days = new Date(cursor.getFullYear(), cursor.getMonth() + 1, 0).getDate(); const cells = Array.from({ length: offset + days }, (_, index) => index < offset ? null : index - offset + 1); const time = String(value || "").slice(11, 16) || "00:00"; const setDate = (day) => { const iso = `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`; onChange(withTime ? `${iso}T${time}` : iso); setOpen(false); }; const setTime = (part, next) => { const [hour, minute] = time.split(":"); onChange(`${String(value).slice(0, 10)}T${part === "hour" ? next : hour}:${part === "minute" ? next : minute}`); }; return <div className="source-picker"><button type="button" className="source-picker-trigger" onClick={() => setOpen(!open)} aria-expanded={open}>{toBrazilianDate(value)}{withTime ? ` ${time}` : ""}<span>▾</span></button>{withTime && <div className="source-time"><select value={time.slice(0, 2)} onChange={(event) => setTime("hour", event.target.value)}>{Array.from({ length: 24 }, (_, item) => String(item).padStart(2, "0")).map((item) => <option key={item}>{item}</option>)}</select><b>:</b><select value={time.slice(3, 5)} onChange={(event) => setTime("minute", event.target.value)}>{Array.from({ length: 60 }, (_, item) => String(item).padStart(2, "0")).map((item) => <option key={item}>{item}</option>)}</select></div>}{open && <div className="source-calendar"><div className="source-calendar-head"><button type="button" onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() - 1, 1))}>‹</button><strong>{cursor.toLocaleDateString("pt-BR", { month: "long", year: "numeric" })}</strong><button type="button" onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1))}>›</button></div><div className="source-calendar-week">{["Seg", "Ter", "Qua", "Qui", "Sex", "Sáb", "Dom"].map((item) => <span key={item}>{item}</span>)}</div><div className="source-calendar-days">{cells.map((day, index) => day ? <button type="button" key={day} className={String(value).slice(0, 10) === `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}` ? "selected" : ""} onClick={() => setDate(day)}>{day}</button> : <i key={`blank-${index}`} />)}</div></div>}</div>; }
function BrazilianDateInput(props) { return <CalendarPicker {...props} />; }
function BrazilianDateTimeInput(props) { return <CalendarPicker {...props} withTime />; }

function UserMenu({ userId }) {
  const [open, setOpen] = useState(false); const current = USERS.find((item) => item.id === userId) || USERS[0];
  return <div className="user-menu"><button className="user-menu-trigger" type="button" aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen(!open)}><span>{current.name}{current.role === "ADMIN" ? " — Admin" : ""}</span><b aria-hidden="true">⌄</b></button>{open && <div className="user-menu-list" role="menu"><div className="source-user-summary"><span>{current.name}</span><small>{current.role === "ADMIN" ? "Administrador" : "Operacional"}</small></div><button type="button" role="menuitem" onClick={() => supabase.auth.signOut()}><span>Sair</span><small>Encerrar sessão</small></button></div>}</div>;
}

