function AccessCard({ children, title, subtitle }) { return <main className="source-access"><section className="source-access-card"><img src={logoAgroVerdeSemFundo} alt="AgroVerde" /><h1>{title}</h1>{subtitle && <p>{subtitle}</p>}{children}</section></main>; }
function PinLogin({ onSignedIn }) { const [pin, setPin] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(false); const account = PIN_ACCOUNTS[pin]; const signIn = async (event) => { event.preventDefault(); setError(""); if (!account) return setError("PIN não reconhecido. Confira e tente novamente."); setLoading(true); const { error: signInError } = await supabase.auth.signInWithPassword({ email: account.email, password }); setLoading(false); if (signInError) return setError("PIN ou senha incorretos."); onSignedIn(); }; return <AccessCard title="Agroverde - Visitas" subtitle="Informe seu PIN e sua senha."><form onSubmit={signIn}><label>PIN</label><input className="source-access-input" inputMode="numeric" pattern="[0-9]*" autoComplete="username" maxLength="1" value={pin} onChange={(event) => setPin(event.target.value.replace(/\D/g, ""))} autoFocus required />{account && <p className="source-pin-identity" aria-live="polite">Acessando como <strong>{account.name}</strong></p>}<label>Senha</label><input className="source-access-input" type="password" autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} required /><button className="primary wide" type="submit" disabled={loading}>{loading ? "Entrando..." : "Entrar"}</button></form>{error && <p className="source-access-error" role="alert">{error}</p>}</AccessCard>; }
function ChangePassword({ onComplete }) { const [password, setPassword] = useState(""); const [confirmation, setConfirmation] = useState(""); const [error, setError] = useState(""); const [saving, setSaving] = useState(false); const submit = async (event) => { event.preventDefault(); setError(""); if (password.length < 10) return setError("Use pelo menos 10 caracteres na nova senha."); if (password !== confirmation) return setError("As senhas não coincidem."); setSaving(true); const { error: passwordError } = await supabase.auth.updateUser({ password }); if (passwordError) { setSaving(false); return setError("Não foi possível alterar a senha. Tente novamente."); } const { error: profileError } = await supabase.rpc("complete_first_password_change"); setSaving(false); if (profileError) return setError("Senha atualizada, mas não foi possível concluir a ativação. Tente novamente."); onComplete(); }; return <AccessCard title="Defina sua nova senha" subtitle="Por segurança, a senha temporária só pode ser usada no primeiro acesso."><form onSubmit={submit}><label>Nova senha</label><input className="source-access-input" type="password" autoComplete="new-password" value={password} onChange={(event) => setPassword(event.target.value)} required /><label>Confirme a nova senha</label><input className="source-access-input" type="password" autoComplete="new-password" value={confirmation} onChange={(event) => setConfirmation(event.target.value)} required /><button className="primary wide" type="submit" disabled={saving}>{saving ? "Salvando..." : "Salvar e continuar"}</button></form>{error && <p className="source-access-error" role="alert">{error}</p>}</AccessCard>; }
function AuthenticatedApp() { const [session, setSession] = useState(undefined); const [profile, setProfile] = useState(undefined); const [error, setError] = useState(""); const loadSession = async () => { const { data: { session: nextSession } } = await supabase.auth.getSession(); setSession(nextSession || null); }; const loadProfile = async () => { if (!session?.user) return; setProfile(undefined); const { data, error: profileError } = await supabase.from("profiles").select("id, full_name, role, must_change_password").eq("id", session.user.id).single(); if (profileError) { setError("Não foi possível carregar seu perfil de acesso. Confirme se a configuração do Supabase foi concluída."); setProfile(null); return; } setError(""); setProfile(data); }; useEffect(() => { loadSession(); const { data: { subscription } } = supabase.auth.onAuthStateChange(() => loadSession()); return () => subscription.unsubscribe(); }, []); useEffect(() => { loadProfile(); }, [session?.user?.id]); if (session === undefined) return <AccessCard title="Carregando acesso" />; if (!session) return <PinLogin onSignedIn={loadSession} />; if (profile === undefined) return <AccessCard title="Carregando perfil" />; if (error || !profile) return <AccessCard title="Acesso indisponível"><p className="source-access-error">{error}</p><button className="primary wide" onClick={() => supabase.auth.signOut()}>Sair</button></AccessCard>; if (profile.must_change_password) return <ChangePassword onComplete={loadProfile} />; return <App profile={profile} onSignOut={() => supabase.auth.signOut()} />; }

function Consultants({ users, onSave }) {
  const [open, setOpen] = useState(false); const [editing, setEditing] = useState(null); const [name, setName] = useState("");
  const consultants = users.filter((item) => item.role === "OPERACIONAL");
  const reset = () => { setEditing(null); setName(""); setOpen(false); };
  const submit = (event) => { event.preventDefault(); const cleanName = text(name, 100); if (!cleanName) return; onSave((current) => ({ ...current, users: editing ? current.users.map((item) => item.id === editing.id ? { ...item, name: cleanName } : item) : [...current.users, { id: `consultant-${Date.now()}`, name: cleanName, role: "OPERACIONAL" }] }), editing ? "Consultor atualizado." : "Consultor cadastrado."); reset(); };
  const edit = (item) => { setEditing(item); setName(item.name); setOpen(true); };
  const remove = (item) => { if (!window.confirm(`Excluir o consultor ${item.name}?`)) return; onSave((current) => ({ ...current, users: current.users.filter((user) => user.id !== item.id) }), "Consultor excluído."); };
  return <div className="content"><section className="toolbar"><button className="primary" onClick={() => { setOpen(!open); if (open) reset(); }}>Novo consultor</button></section>{open && <form className="form-card inline-form" onSubmit={submit}><h3>{editing ? "Editar consultor" : "Novo consultor"}</h3><Field label="Nome do consultor" required value={name} onChange={setName} /><div className="row-actions"><button className="ghost small-action" type="button" onClick={reset}>Cancelar</button><button className="primary" type="submit">{editing ? "Salvar alterações" : "Cadastrar consultor"}</button></div></form>}<Panel title="Consultores cadastrados">{consultants.length ? consultants.map((item) => <article className="row-card" key={item.id}><div><strong>{item.name}</strong><span>Consultor</span></div><div className="row-actions"><button className="ghost small-action" onClick={() => edit(item)}>Editar</button><button className="icon-btn danger" title={`Excluir ${item.name}`} aria-label={`Excluir ${item.name}`} onClick={() => remove(item)}>×</button></div></article>) : <Empty>Nenhum consultor cadastrado.</Empty>}</Panel></div>;
}

function App({ profile }) {
  const [data, setData] = useState(loadData); const [userId] = useState(profile.id); const [view, setView] = useState("dashboard"); const [activePlan, setActivePlan] = useState(null); const [notice, setNotice] = useState(""); const [navOpen, setNavOpen] = useState(false);
  const user = { id: profile.id, name: profile.full_name, role: profile.role }; USERS = [user, ...data.users.filter((item) => item.id !== user.id)]; const isAdmin = user.role === "ADMIN";
  const clientMap = useMemo(() => new Map(data.clients.map((item) => [item.id, item])), [data.clients]); const farmMap = useMemo(() => new Map(data.farms.map((item) => [item.id, item])), [data.farms]);
  useEffect(() => localStorage.setItem(STORAGE_KEY, JSON.stringify(data)), [data]); useEffect(() => { if (!notice) return undefined; const timer = setTimeout(() => setNotice(""), 3500); return () => clearTimeout(timer); }, [notice]);
  useEffect(() => {
    if (!data.visits.some((visit) => !visit.planId)) return;
    setData((current) => {
      let nextPlanId = idFor(current.plans);
      const plans = [...current.plans];
      const visits = current.visits.map((visit) => {
        if (visit.planId) return visit;
        const planId = nextPlanId++;
        plans.push({ id: planId, userId: visit.userId || "seller-1", clientId: visit.clientId, farmId: visit.farmId, scheduledDate: String(visit.visitedAt).slice(0, 10), status: "COMPLETED", notDoneReason: "", notDoneNote: "" });
        return { ...visit, planId };
      });
      return { ...current, plans, visits };
    });
  }, [data.visits, data.plans]);
  const save = (updater, message) => { setData(updater); setNotice(message); }; const navigate = (next, plan = null) => { setActivePlan(plan); setView(next); setNavOpen(false); };
  useEffect(() => { const finishVisit = () => { setActivePlan(null); setView("schedule"); }; window.addEventListener("agroverde:visit-saved", finishVisit); return () => window.removeEventListener("agroverde:visit-saved", finishVisit); }, []);
  const nav = [["dashboard", "▦", "Início"], ["schedule", "▤", "Programação"], ["newVisit", "↗", "Nova visita"], ["clients", "◉", "Clientes"], ["farms", "⌂", "Fazendas"], ...(isAdmin ? [["reports", "▥", "Relatórios"]] : [])];
  return <div className="app-shell source-app">{navOpen && <button className="scrim" type="button" aria-label="Fechar navegação" onClick={() => setNavOpen(false)} />}<aside className={`sidebar${navOpen ? " open" : ""}`}><div className="sidebar-head"><img className="sidebar-logo" src={logoAgroVerdeSemFundo} alt="AgroVerde" /></div><nav>{nav.map(([id, icon, label]) => <button key={id} className={view === id ? "active" : ""} onClick={() => navigate(id)}><span className="source-icon" aria-hidden="true">{icon}</span>{label}</button>)}</nav><p className="source-demo-note">Perfis demonstrativos. A autenticação segura será conectada ao backend.</p></aside><main className="main"><header className="topbar"><button className="mobile-nav-toggle" type="button" aria-label="Abrir navegação" aria-expanded={navOpen} onClick={() => setNavOpen(!navOpen)}><i /><i /><i /></button><div><span>{isAdmin ? "GESTÃO" : "OPERAÇÃO EM CAMPO"}</span><h2>{nav.find(([id]) => id === view)?.[2] || "AgroVerde"}</h2></div><UserMenu userId={userId} onChange={(nextUserId) => { setUserId(nextUserId); setView("dashboard"); }} /></header>{notice && <div className="source-notice">{notice}</div>}{view === "dashboard" && <Dashboard data={data} user={user} isAdmin={isAdmin} clients={clientMap} farms={farmMap} onNavigate={navigate} />}{view === "schedule" && <Schedule data={data} user={user} isAdmin={isAdmin} clients={clientMap} farms={farmMap} onSave={save} onVisit={(plan) => navigate("newVisit", plan)} />}{view === "newVisit" && <VisitForm data={data} user={user} isAdmin={isAdmin} activePlan={activePlan} onSave={save} />}{view === "clients" && <Clients clients={data.clients} onSave={save} />}{view === "farms" && <Farms farms={data.farms} clients={data.clients} clientMap={clientMap} onSave={save} />}{view === "consultants" && isAdmin && <Consultants users={USERS} onSave={save} />}{view === "reports" && isAdmin && <Reports data={data} clients={clientMap} farms={farmMap} />}</main></div>;
}

function Dashboard({ data, user, isAdmin, clients, farms, onNavigate }) {
  const plans = data.plans.filter((item) => isAdmin || item.userId === user.id); const visits = data.visits.filter((item) => isAdmin || item.userId === user.id); const today = new Date().toISOString().slice(0, 10); const pending = plans.filter((item) => item.status === "PLANNED");
  return <div className="content"><section className="source-hero"><img src={logoAgroVerde} alt="AgroVerde" /><div><span>Gestão em campo</span><h1>{isAdmin ? "Acompanhe a operação comercial da AgroVerde." : "Planeje e registre as visitas da sua semana."}</h1><button className="primary" onClick={() => onNavigate(isAdmin ? "reports" : "schedule")}>{isAdmin ? "Ver relatórios" : "Ver programação"}</button></div></section><section className="metrics"><Metric label={isAdmin ? "Clientes" : "Minha programação"} value={isAdmin ? data.clients.length : plans.length} detail={isAdmin ? "cadastros compartilhados" : "visitas na semana"} /><Metric label="Pendentes" value={pending.length} detail="programadas" /><Metric label="Visitas hoje" value={visits.filter((item) => String(item.visitedAt).slice(0, 10) === today).length} detail="realizadas" /><Metric label="Fazendas" value={data.farms.length} detail="cadastros compartilhados" /></section><Panel title={isAdmin ? "Últimas visitas registradas" : "Próximas visitas"}>{(isAdmin ? visits.map((item) => ({ ...item, date: item.visitedAt })) : pending.map((item) => ({ ...item, date: item.scheduledDate }))).sort((a, b) => String(b.date).localeCompare(String(a.date))).slice(0, 5).map((item) => <article className="row-card" key={item.id}><div><strong>{clients.get(item.clientId)?.name || "Cliente não informado"}</strong><span>{farms.get(item.farmId)?.name || "Fazenda não informada"} · {dateLabel(item.date)}</span></div><small className="pill">{isAdmin ? "realizada" : "programada"}</small></article>) || <Empty>Nenhum registro para exibir.</Empty>}</Panel></div>;
}

function ScheduleLegacy({ data, user, isAdmin, clients, farms, onSave, onVisit }) {
  const [week, setWeek] = useState(mondayOf()); const [open, setOpen] = useState(false); const [editing, setEditing] = useState(null); const [form, setForm] = useState({ userId: isAdmin ? "seller-1" : user.id, clientId: "", farmId: "", scheduledDate: mondayOf() }); const [notDone, setNotDone] = useState(null); const [reason, setReason] = useState(""); const [note, setNote] = useState("");
  const plans = data.plans.filter((item) => inWeek(item.scheduledDate, week) && (isAdmin || item.userId === user.id)).sort((a, b) => a.scheduledDate.localeCompare(b.scheduledDate)); const eligibleFarms = data.farms.filter((farm) => !form.clientId || !farm.clientId || farm.clientId === Number(form.clientId));
  function add(event) { event.preventDefault(); if (!form.clientId || !form.scheduledDate) return; const plan = { id: editing?.id || idFor(data.plans), userId: form.userId, clientId: Number(form.clientId), farmId: Number(form.farmId) || null, scheduledDate: form.scheduledDate, status: editing?.status || "PLANNED", notDoneReason: editing?.notDoneReason || "", notDoneNote: editing?.notDoneNote || "" }; onSave((current) => ({ ...current, plans: editing ? current.plans.map((item) => item.id === editing.id ? plan : item) : [...current.plans, plan] }), editing ? "Programação atualizada." : "Visita adicionada à programação."); setOpen(false); setEditing(null); }
  function fail(event) { event.preventDefault(); if (!reason) return; onSave((current) => ({ ...current, plans: current.plans.map((plan) => plan.id === notDone.id ? { ...plan, status: "NOT_DONE", notDoneReason: reason, notDoneNote: reason === "Outro" ? text(note, 500) : "" } : plan) }), "Visita marcada como não realizada."); setNotDone(null); setReason(""); setNote(""); }
  return <div className="content"><section className="toolbar source-week-bar"><label>Semana de</label><input type="date" value={week} onChange={(event) => setWeek(mondayOf(`${event.target.value}T12:00:00`))} /><button className="primary" onClick={() => setOpen(!open)}>Adicionar visita</button></section>{open && <form className="form-card inline-form" onSubmit={add}><h3>Programar visita</h3>{isAdmin && <><label>Consultor responsável</label><select value={form.userId} onChange={(event) => setForm({ ...form, userId: event.target.value })}>{USERS.filter((item) => item.role === "OPERACIONAL").map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></>}<label>Cliente</label><select required value={form.clientId} onChange={(event) => setForm({ ...form, clientId: event.target.value, farmId: "" })}><option value="">Selecione</option>{data.clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select><label>Fazenda</label><select value={form.farmId} onChange={(event) => setForm({ ...form, farmId: event.target.value })}><option value="">Não informar agora</option>{eligibleFarms.map((farm) => <option key={farm.id} value={farm.id}>{farm.name}</option>)}</select><Field label="Data programada" type="date" required value={form.scheduledDate} onChange={(scheduledDate) => setForm({ ...form, scheduledDate })} /><button className="primary" type="submit">Salvar programação</button></form>}<Panel title="Visitas programadas">{plans.length ? plans.map((plan) => <article className="row-card" key={plan.id}><div><strong>{clients.get(plan.clientId)?.name || "Cliente não informado"}</strong><span>{farms.get(plan.farmId)?.name || "Fazenda não informada"} · {dateLabel(plan.scheduledDate)}</span>{plan.status === "NOT_DONE" && <span className="source-warning">Não realizada: {plan.notDoneReason}{plan.notDoneNote ? ` — ${plan.notDoneNote}` : ""}</span>}</div><div className="row-actions">{plan.status === "PLANNED" && <><button className="ghost small-action" onClick={() => onVisit(plan)}>Realizada</button><button className="icon-btn danger" title="Não realizada" onClick={() => setNotDone(plan)}>×</button></>}{plan.status === "COMPLETED" && <small className="pill realizada">realizada</small>}</div></article>) : <Empty>Nenhuma visita programada nesta semana.</Empty>}</Panel>{notDone && <form className="form-card inline-form" onSubmit={fail}><h3>Motivo da visita não realizada</h3><label>Motivo obrigatório</label><select required value={reason} onChange={(event) => setReason(event.target.value)}><option value="">Selecione</option>{NOT_DONE_REASONS.map((item) => <option key={item}>{item}</option>)}</select>{reason === "Outro" && <><label>Descreva o motivo</label><textarea required value={note} onChange={(event) => setNote(event.target.value)} /></>}<button className="primary" type="submit">Confirmar</button></form>}</div>;
}

function VisitFormLegacy({ data, user, isAdmin, activePlan, onSave }) {
  const plan = activePlan || {}; const [form, setForm] = useState({ planId: plan.id || "", userId: plan.userId || (isAdmin ? "seller-1" : user.id), clientId: plan.clientId || "", farmId: plan.farmId || "", visitedAt: new Date().toISOString().slice(0, 16), developed: "", types: [], businessType: "", saleValue: "", nextAction: "" }); const closing = form.types.includes("CLOSING"); const farms = data.farms.filter((farm) => !form.clientId || !farm.clientId || farm.clientId === Number(form.clientId));
  const toggle = (type) => setForm({ ...form, types: form.types.includes(type) ? form.types.filter((item) => item !== type) : [...form.types, type] });
  function submit(event) { event.preventDefault(); if (!form.clientId || !form.developed || !form.types.length) return; const visit = { id: idFor(data.visits), userId: form.userId, planId: Number(form.planId) || null, clientId: Number(form.clientId), farmId: Number(form.farmId) || null, visitedAt: new Date(form.visitedAt).toISOString(), developed: text(form.developed, 2000), types: form.types, businessType: closing ? text(form.businessType, 100) : "", saleValue: closing ? Number(form.saleValue) || 0 : 0, nextAction: text(form.nextAction, 500) }; onSave((current) => ({ ...current, visits: [visit, ...current.visits], plans: current.plans.map((item) => item.id === visit.planId ? { ...item, status: "COMPLETED" } : item) }), "Visita registrada com sucesso."); }
  return <div className="content visit-flow"><form className="form-card" onSubmit={submit}><h3>Registrar visita</h3>{isAdmin && <><label>Consultor responsável</label><select value={form.userId} onChange={(event) => setForm({ ...form, userId: event.target.value })}>{USERS.filter((item) => item.role === "OPERACIONAL").map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></>}<label>Data e hora da visita</label><input type="datetime-local" required value={form.visitedAt} onChange={(event) => setForm({ ...form, visitedAt: event.target.value })} /><label>Nome do cliente</label><select required value={form.clientId} onChange={(event) => setForm({ ...form, clientId: event.target.value, farmId: "" })}><option value="">Selecione</option>{data.clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select><label>Nome da propriedade / fazenda</label><select value={form.farmId} onChange={(event) => setForm({ ...form, farmId: event.target.value })}><option value="">Não informar</option>{farms.map((farm) => <option key={farm.id} value={farm.id}>{farm.name}</option>)}</select><label>O que foi desenvolvido / oferecido</label><textarea required value={form.developed} onChange={(event) => setForm({ ...form, developed: event.target.value })} placeholder="Descreva o atendimento, produtos e oportunidades." /><label>Tipo de visita</label><div className="checks source-checks">{VISIT_TYPES.map(([type, label]) => <label key={type}><input type="checkbox" checked={form.types.includes(type)} onChange={() => toggle(type)} /> {label}</label>)}</div>{closing && <div className="embedded-form"><h3>Fechamento de negócio</h3><label>Tipo de negócio</label><select value={form.businessType} onChange={(event) => setForm({ ...form, businessType: event.target.value })}><option value="">Selecione</option>{PRODUCT_LINES.map((item) => <option key={item}>{item}</option>)}</select><Field label="Valor final da venda (R$)" type="number" min="0" step="0.01" value={form.saleValue} onChange={(saleValue) => setForm({ ...form, saleValue })} /></div>}<Field label="Próxima ação" value={form.nextAction} onChange={(nextAction) => setForm({ ...form, nextAction })} /><button className="primary wide" type="submit">Salvar visita</button></form></div>;
}

function Clients({ clients, onSave }) { const [open, setOpen] = useState(false); const [form, setForm] = useState({ name: "", phone: "", whatsapp: "", city: "", state: "", mainActivity: "", notes: "" }); function submit(event) { event.preventDefault(); if (!text(form.name)) return; onSave((current) => ({ ...current, clients: [...current.clients, { id: idFor(clients), ...form, name: text(form.name, 180) }] }), "Cliente cadastrado com sucesso."); setOpen(false); } return <div className="content"><section className="toolbar"><button className="primary" onClick={() => setOpen(!open)}>Novo cliente</button></section>{open && <form className="form-card inline-form" onSubmit={submit}><h3>Novo cliente</h3><Field label="Nome ou razão social" required value={form.name} onChange={(name) => setForm({ ...form, name })} /><div className="source-grid"><Field label="Telefone" value={form.phone} onChange={(phone) => setForm({ ...form, phone })} /><Field label="WhatsApp" value={form.whatsapp} onChange={(whatsapp) => setForm({ ...form, whatsapp })} /></div><StateCityFields state={form.state} city={form.city} onChange={({ state, city }) => setForm({ ...form, state, city })} /><Field label="Atividade principal" value={form.mainActivity} onChange={(mainActivity) => setForm({ ...form, mainActivity })} /><label>Observações</label><textarea value={form.notes} onChange={(event) => setForm({ ...form, notes: event.target.value })} /><button className="primary" type="submit">Salvar cliente</button></form>}<Panel title="Clientes compartilhados">{clients.length ? clients.map((client) => <article className="row-card" key={client.id}><div><strong>{client.name}</strong><span>{[client.mainActivity, client.city, client.state].filter(Boolean).join(" · ") || "Sem dados complementares"}</span></div><small className="pill">ativo</small></article>) : <Empty>Nenhum cliente cadastrado ainda.</Empty>}</Panel></div>; }
function Farms({ farms, clients, clientMap, onSave }) { const [open, setOpen] = useState(false); const [form, setForm] = useState({ name: "", clientId: "", city: "", state: "", mainActivity: "" }); function submit(event) { event.preventDefault(); if (!text(form.name)) return; onSave((current) => ({ ...current, farms: [...current.farms, { id: idFor(farms), ...form, clientId: Number(form.clientId) || null, name: text(form.name, 180) }] }), "Fazenda cadastrada com sucesso."); setOpen(false); } return <div className="content"><section className="toolbar"><button className="primary" onClick={() => setOpen(!open)}>Nova fazenda</button></section>{open && <form className="form-card inline-form" onSubmit={submit}><h3>Nova fazenda</h3><Field label="Nome da fazenda" required value={form.name} onChange={(name) => setForm({ ...form, name })} /><label>Cliente responsável</label><select value={form.clientId} onChange={(event) => setForm({ ...form, clientId: event.target.value })}><option value="">Não vincular agora</option>{clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select><StateCityFields state={form.state} city={form.city} onChange={({ state, city }) => setForm({ ...form, state, city })} /><Field label="Atividade principal" value={form.mainActivity} onChange={(mainActivity) => setForm({ ...form, mainActivity })} /><button className="primary" type="submit">Salvar fazenda</button></form>}<Panel title="Fazendas compartilhadas">{farms.length ? farms.map((farm) => <article className="row-card" key={farm.id}><div><strong>{farm.name}</strong><span>{[clientMap.get(farm.clientId)?.name, farm.mainActivity, farm.city].filter(Boolean).join(" · ") || "Sem dados complementares"}</span></div><small className="pill">ativa</small></article>) : <Empty>Nenhuma fazenda cadastrada ainda.</Empty>}</Panel></div>; }
function ReportsLegacy({ data, clients, farms }) { const [week, setWeek] = useState(mondayOf()); const visits = data.visits.filter((visit) => inWeek(visit.visitedAt, week)); const by = (type) => visits.filter((visit) => visit.types.includes(type)); const deals = by("CLOSING").filter((visit) => visit.saleValue > 0); const total = deals.reduce((sum, visit) => sum + visit.saleValue, 0); return <div className="content"><section className="toolbar source-week-bar"><label>Semana de</label><input type="date" value={week} onChange={(event) => setWeek(mondayOf(`${event.target.value}T12:00:00`))} /></section><section className="metrics"><Metric label="Clientes visitados" value={new Set(visits.map((visit) => visit.clientId).filter(Boolean)).size} detail="na semana" /><Metric label="Relacionamento" value={by("RELATIONSHIP").length} detail="visitas" /><Metric label="Prospecção" value={by("PROSPECTING").length} detail="visitas" /><Metric label="Fechamentos" value={by("CLOSING").length} detail="visitas" /></section><section className="metrics source-deals"><Metric label="Negócios fechados" value={deals.length} detail="com valor informado" /><Metric label="Valor consolidado" value={money.format(total)} detail="em vendas" /></section><Panel title="Visitas da semana">{visits.length ? visits.map((visit) => <article className="row-card" key={visit.id}><div><strong>{clients.get(visit.clientId)?.name || "Cliente não informado"}</strong><span>{farms.get(visit.farmId)?.name || "Fazenda não informada"} · {dateLabel(visit.visitedAt)} · {VISIT_TYPES.filter(([id]) => visit.types.includes(id)).map(([, label]) => label).join(", ")}</span>{visit.saleValue > 0 && <span className="follow-up-text">Venda: {money.format(visit.saleValue)} {visit.businessType ? `— ${visit.businessType}` : ""}</span>}</div></article>) : <Empty>Nenhuma visita registrada nesta semana.</Empty>}</Panel></div>; }

function ScheduleLegacy2({ data, user, isAdmin, clients, farms, onSave, onVisit }) {
  const [week, setWeek] = useState(mondayOf());
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ userId: isAdmin ? "seller-1" : user.id, clientId: "", farmId: "", scheduledDate: mondayOf() });
  const [notDone, setNotDone] = useState(null);
  const [reason, setReason] = useState("");
  const [note, setNote] = useState("");
  const plans = data.plans.filter((item) => inWeek(item.scheduledDate, week) && (isAdmin || item.userId === user.id)).sort((a, b) => a.scheduledDate.localeCompare(b.scheduledDate));
  const eligibleFarms = data.farms.filter((farm) => !form.clientId || !farm.clientId || farm.clientId === Number(form.clientId));
  const resetForm = () => { setEditing(null); setForm({ userId: isAdmin ? "seller-1" : user.id, clientId: "", farmId: "", scheduledDate: week }); };
  function submitPlan(event) {
    event.preventDefault(); if (!form.clientId || !form.scheduledDate) return;
    const plan = { id: editing?.id || idFor(data.plans), userId: form.userId, clientId: Number(form.clientId), farmId: Number(form.farmId) || null, scheduledDate: form.scheduledDate, status: editing?.status || "PLANNED", notDoneReason: editing?.notDoneReason || "", notDoneNote: editing?.notDoneNote || "" };
    onSave((current) => ({ ...current, plans: editing ? current.plans.map((item) => item.id === editing.id ? plan : item) : [...current.plans, plan] }), editing ? "Programação atualizada." : "Visita adicionada à programação."); setOpen(false); resetForm();
  }
  function edit(plan) { setEditing(plan); setForm({ userId: plan.userId, clientId: String(plan.clientId || ""), farmId: String(plan.farmId || ""), scheduledDate: plan.scheduledDate }); setOpen(true); }
  function markNotDone(event) { event.preventDefault(); if (!reason) return; onSave((current) => ({ ...current, plans: current.plans.map((item) => item.id === notDone.id ? { ...item, status: "NOT_DONE", notDoneReason: reason, notDoneNote: reason === "Outro" ? text(note, 500) : "" } : item) }), "Visita marcada como não realizada."); setNotDone(null); setReason(""); setNote(""); }
  return <div className="content"><section className="toolbar source-week-bar"><label>Semana de</label><input type="date" value={week} onChange={(event) => setWeek(mondayOf(`${event.target.value}T12:00:00`))} /><button className="primary" onClick={() => { resetForm(); setOpen(true); }}>Adicionar visita</button></section>{open && <form className="form-card inline-form" onSubmit={submitPlan}><h3>{editing ? "Alterar programação" : "Programar visita"}</h3>{isAdmin && <><label>Consultor responsável</label><select value={form.userId} onChange={(event) => setForm({ ...form, userId: event.target.value })}>{USERS.filter((item) => item.role === "OPERACIONAL").map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></>}<label>Cliente</label><select required value={form.clientId} onChange={(event) => setForm({ ...form, clientId: event.target.value, farmId: "" })}><option value="">Selecione</option>{data.clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select><label>Fazenda</label><select value={form.farmId} onChange={(event) => setForm({ ...form, farmId: event.target.value })}><option value="">Não informar agora</option>{eligibleFarms.map((farm) => <option key={farm.id} value={farm.id}>{farm.name}</option>)}</select><Field label="Data programada" type="date" required value={form.scheduledDate} onChange={(scheduledDate) => setForm({ ...form, scheduledDate })} /><button className="primary" type="submit">{editing ? "Salvar alteração" : "Salvar programação"}</button></form>}<Panel title="Visitas programadas">{plans.length ? plans.map((plan) => <article className="row-card" key={plan.id}><div><strong>{clients.get(plan.clientId)?.name || "Cliente não informado"}</strong><span>{farms.get(plan.farmId)?.name || "Fazenda não informada"} · {dateLabel(plan.scheduledDate)}</span>{plan.status === "NOT_DONE" && <span className="source-warning">Não realizada: {plan.notDoneReason}{plan.notDoneNote ? ` — ${plan.notDoneNote}` : ""}</span>}</div><div className="row-actions">{plan.status === "PLANNED" && <><button className="ghost small-action" onClick={() => edit(plan)}>Editar</button><button className="ghost small-action" onClick={() => onVisit(plan)}>Realizada</button><button className="icon-btn danger" title="Não realizada" onClick={() => setNotDone(plan)}>×</button></>}{plan.status === "COMPLETED" && <small className="pill realizada">realizada</small>}</div></article>) : <Empty>Nenhuma visita programada nesta semana.</Empty>}</Panel>{notDone && <form className="form-card inline-form" onSubmit={markNotDone}><h3>Motivo da visita não realizada</h3><label>Motivo obrigatório</label><select required value={reason} onChange={(event) => setReason(event.target.value)}><option value="">Selecione</option>{NOT_DONE_REASONS.map((item) => <option key={item}>{item}</option>)}</select>{reason === "Outro" && <><label>Descreva o motivo</label><textarea required value={note} onChange={(event) => setNote(event.target.value)} /></>}<button className="primary" type="submit">Confirmar</button></form>}</div>;
}

function Schedule({ data, user, isAdmin, clients, farms, onSave, onVisit }) {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().slice(0, 10)); const [open, setOpen] = useState(false); const [form, setForm] = useState({ userId: user.role === "ADMIN" ? "seller-1" : user.id, clientId: "", farmId: "", scheduledDate: new Date().toISOString().slice(0, 10) }); const [notDone, setNotDone] = useState(null); const [reason, setReason] = useState(""); const [note, setNote] = useState("");
  const plans = data.plans.filter((item) => inWeek(item.scheduledDate, selectedDate) && (isAdmin || item.userId === user.id)).sort((a, b) => a.scheduledDate.localeCompare(b.scheduledDate)); const eligible = data.farms.filter((farm) => !form.clientId || !farm.clientId || farm.clientId === Number(form.clientId));
  function add(event) { event.preventDefault(); if (!form.clientId || !form.scheduledDate) return; const plan = { id: idFor(data.plans), userId: form.userId, clientId: Number(form.clientId), farmId: Number(form.farmId) || null, scheduledDate: form.scheduledDate, status: "PLANNED", notDoneReason: "", notDoneNote: "" }; onSave((current) => ({ ...current, plans: [...current.plans, plan] }), "Visita adicionada à programação."); setOpen(false); }
  function fail(event) { event.preventDefault(); if (!reason) return; onSave((current) => ({ ...current, plans: current.plans.map((item) => item.id === notDone.id ? { ...item, status: "NOT_DONE", notDoneReason: reason, notDoneNote: reason === "Outro" ? text(note) : "" } : item) }), "Visita marcada como não realizada."); setNotDone(null); }
  return <div className="content"><section className="toolbar source-week-bar"><div><label>Data selecionada</label><BrazilianDateInput value={selectedDate} onChange={setSelectedDate} /></div><button className="primary" onClick={() => setOpen(!open)}>Adicionar visita</button></section>{open && <form className="form-card inline-form" onSubmit={add}><h3>Programar visita</h3>{isAdmin && <><label>Consultor responsável</label><select value={form.userId} onChange={(event) => setForm({ ...form, userId: event.target.value })}>{USERS.filter((item) => item.role === "OPERACIONAL").map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></>}<label>Cliente</label><select required value={form.clientId} onChange={(event) => setForm({ ...form, clientId: event.target.value, farmId: "" })}><option value="">Selecione</option>{data.clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select><label>Fazenda</label><select value={form.farmId} onChange={(event) => setForm({ ...form, farmId: event.target.value })}><option value="">Não informar agora</option>{eligible.map((farm) => <option key={farm.id} value={farm.id}>{farm.name}</option>)}</select><label>Data programada</label><BrazilianDateInput required value={form.scheduledDate} onChange={(scheduledDate) => setForm({ ...form, scheduledDate })} /><button className="primary" type="submit">Salvar programação</button></form>}<Panel title="Visitas programadas">{plans.length ? plans.map((plan) => <article className="row-card" key={plan.id}><div><strong>{clients.get(plan.clientId)?.name || "Cliente não informado"}</strong><span>{farms.get(plan.farmId)?.name || "Fazenda não informada"} · {dateLabel(plan.scheduledDate)}</span>{plan.status === "NOT_DONE" && <span className="source-warning">Não realizada: {plan.notDoneReason}</span>}</div><div className="row-actions">{plan.status === "PLANNED" && <><button className="ghost small-action" onClick={() => onVisit(plan)}>Realizada</button><button className="icon-btn danger" onClick={() => setNotDone(plan)}>×</button></>}{plan.status === "COMPLETED" && <small className="pill realizada">realizada</small>}</div></article>) : <Empty>Nenhuma visita programada nesta semana.</Empty>}</Panel>{notDone && <form className="form-card inline-form" onSubmit={fail}><h3>Motivo da visita não realizada</h3><label>Motivo obrigatório</label><select required value={reason} onChange={(event) => setReason(event.target.value)}><option value="">Selecione</option>{NOT_DONE_REASONS.map((item) => <option key={item}>{item}</option>)}</select>{reason === "Outro" && <><label>Descreva o motivo</label><textarea required value={note} onChange={(event) => setNote(event.target.value)} /></>}<button className="primary" type="submit">Confirmar</button></form>}</div>;
}
function VisitFormLegacy2({ data, user, isAdmin, activePlan, onSave }) { const plan = activePlan || {}; const [form, setForm] = useState({ planId: plan.id || "", userId: plan.userId || (isAdmin ? "seller-1" : user.id), clientId: plan.clientId || "", farmId: plan.farmId || "", visitedAt: new Date().toISOString().slice(0, 16), developed: "", types: [], businessType: "", saleValue: "", nextAction: "" }); const closing = form.types.includes("CLOSING"); const farms = data.farms.filter((farm) => !form.clientId || !farm.clientId || farm.clientId === Number(form.clientId)); const toggle = (type) => setForm({ ...form, types: form.types.includes(type) ? form.types.filter((item) => item !== type) : [...form.types, type] }); function submit(event) { event.preventDefault(); if (!form.clientId || !form.developed || !form.types.length) return; const visit = { id: idFor(data.visits), ...form, planId: Number(form.planId) || null, clientId: Number(form.clientId), farmId: Number(form.farmId) || null, visitedAt: new Date(form.visitedAt).toISOString(), developed: text(form.developed), businessType: closing ? text(form.businessType) : "", saleValue: closing ? Number(form.saleValue) || 0 : 0 }; onSave((current) => ({ ...current, visits: [visit, ...current.visits], plans: current.plans.map((item) => item.id === visit.planId ? { ...item, status: "COMPLETED" } : item) }), "Visita registrada com sucesso."); } return null; }
function Reports({ data, clients, farms }) { const [selectedDate, setSelectedDate] = useState(new Date().toISOString().slice(0, 10)); const visits = data.visits.filter((visit) => inWeek(visit.visitedAt, selectedDate)); const by = (type) => visits.filter((visit) => visit.types.includes(type)); const deals = by("CLOSING").filter((visit) => visit.saleValue > 0); const total = deals.reduce((sum, visit) => sum + visit.saleValue, 0); return <div className="content"><section className="toolbar source-week-bar"><div><label>Data selecionada</label><BrazilianDateInput value={selectedDate} onChange={setSelectedDate} /></div></section><section className="metrics"><Metric label="Clientes visitados" value={new Set(visits.map((visit) => visit.clientId).filter(Boolean)).size} detail="na semana" /><Metric label="Relacionamento" value={by("RELATIONSHIP").length} detail="visitas" /><Metric label="Prospecção" value={by("PROSPECTING").length} detail="visitas" /><Metric label="Fechamentos" value={by("CLOSING").length} detail="visitas" /></section><section className="metrics source-deals"><Metric label="Negócios fechados" value={deals.length} detail="com valor informado" /><Metric label="Valor consolidado" value={money.format(total)} detail="em vendas" /></section><Panel title="Visitas da semana">{visits.length ? visits.map((visit) => <article className="row-card" key={visit.id}><div><strong>{clients.get(visit.clientId)?.name || "Cliente não informado"}</strong><span>{farms.get(visit.farmId)?.name || "Fazenda não informada"} · {dateLabel(visit.visitedAt)}</span></div></article>) : <Empty>Nenhuma visita registrada nesta semana.</Empty>}</Panel></div>; }

function VisitForm({ data, user, isAdmin, activePlan, onSave }) {
  const plan = activePlan || {}; const [saving, setSaving] = useState(false); const [form, setForm] = useState({ planId: plan.id || "", userId: plan.userId || (isAdmin ? "seller-1" : user.id), clientId: plan.clientId || "", farmId: plan.farmId || "", visitedAt: new Date().toISOString().slice(0, 16), developed: "", types: [], businessType: "", saleValue: "", nextAction: "" }); const closing = form.types.includes("CLOSING"); const farms = data.farms.filter((farm) => !form.clientId || !farm.clientId || farm.clientId === Number(form.clientId)); const toggle = (type) => setForm({ ...form, types: form.types.includes(type) ? form.types.filter((item) => item !== type) : [...form.types, type] });
  function submit(event) { event.preventDefault(); if (saving || !form.clientId || !form.developed || !form.types.length) return; setSaving(true); const visit = { id: idFor(data.visits), ...form, planId: Number(form.planId) || null, clientId: Number(form.clientId), farmId: Number(form.farmId) || null, visitedAt: new Date(form.visitedAt).toISOString(), developed: text(form.developed), businessType: closing ? text(form.businessType) : "", saleValue: closing ? Number(form.saleValue) || 0 : 0 }; onSave((current) => ({ ...current, visits: [visit, ...current.visits], plans: current.plans.map((item) => item.id === visit.planId ? { ...item, status: "COMPLETED" } : item) }), "Visita registrada com sucesso."); window.dispatchEvent(new Event("agroverde:visit-saved")); }
  return <div className="content visit-flow"><form className="form-card" onSubmit={submit}><h3>Registrar visita</h3><label>Data e hora da visita</label><BrazilianDateTimeInput required value={form.visitedAt} onChange={(visitedAt) => setForm({ ...form, visitedAt })} /><label>Nome do cliente</label><select required value={form.clientId} onChange={(event) => setForm({ ...form, clientId: event.target.value, farmId: "" })}><option value="">Selecione</option>{data.clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select><label>Nome da propriedade / fazenda</label><select value={form.farmId} onChange={(event) => setForm({ ...form, farmId: event.target.value })}><option value="">Não informar</option>{farms.map((farm) => <option key={farm.id} value={farm.id}>{farm.name}</option>)}</select><label>O que foi desenvolvido / oferecido</label><textarea required value={form.developed} onChange={(event) => setForm({ ...form, developed: event.target.value })} /><label>Tipo de visita</label><div className="checks source-checks">{VISIT_TYPES.map(([type, label]) => <label key={type}><input type="checkbox" checked={form.types.includes(type)} onChange={() => toggle(type)} /> {label}</label>)}</div>{closing && <div className="embedded-form"><h3>Fechamento de negócio</h3><label>Tipo de negócio</label><select value={form.businessType} onChange={(event) => setForm({ ...form, businessType: event.target.value })}><option value="">Selecione</option>{PRODUCT_LINES.map((item) => <option key={item}>{item}</option>)}</select><Field label="Valor final da venda (R$)" type="number" min="0" step="0.01" value={form.saleValue} onChange={(saleValue) => setForm({ ...form, saleValue })} /></div>}<Field label="Próxima ação" value={form.nextAction} onChange={(nextAction) => setForm({ ...form, nextAction })} /><button className="primary wide" type="submit" disabled={saving}>{saving ? "Salvando..." : "Salvar visita"}</button></form></div>;
}
createRoot(document.getElementById("root")).render(<React.StrictMode><AuthenticatedApp /></React.StrictMode>);
